parms.snippet:
// Expose channel prim keys as spreadsheet-visible attributes
f[]@key_frames = chprim_keytimes(0, @primnum);
// convert seconds to frames
foreach(int i; float t; f[]@key_frames) {
    f[]@key_frames[i] = t * $FPS + 1;
}
f[]@key_values = chprim_keyvalues(0, @primnum);
i@num_keys = len(f[]@key_values);
f@ch_start = chprim_start(0, @primnum);
f@ch_end = chprim_end(0, @primnum);
